139: // EndChecked turns an end phase check into the kill, begin-next or stop plan.
140: func (l *Loop) EndChecked(e gitrules.End, now time.Time) []Action {
141: 	if l.State != "running" && l.State != "paused" {
142: 		return nil
143: 	}
144: 	if !e.OK {
145: 		reason := strings.Join(e.Problems, "; ")
146: 		l.State = "waiting"
147: 		l.Stop = &control.Stop{Kind: "not_pushed", Phase: l.Phase, Reason: reason, At: now}
148: 		l.Queue.Stop(reason)
149: 		return []Action{
150: 			{Kind: "post", Milestone: control.Milestone{Kind: "stop", Headline: l.Phase + " not pushed", Numbers: reason}},
151: 		}
152: 	}
153: 
154: 	l.StretchUSD += l.SessionUSD
155: 	finished := l.Phase
156: 	next := ""
157: 	if l.Queue.Index+1 < len(l.Queue.Phases) {
158: 		next = l.Queue.Phases[l.Queue.Index+1].ID
159: 	}
160: 	out, _ := l.Queue.Done(finished, next)
161: 
162: 	actions := []Action{{Kind: "kill"}}
163: 	switch out.Stop {
164: 	case "":
165: 		l.Stop = nil
166: 		l.Nudged = false
167: 		l.Alerted = false
168: 		l.SessionUSD = 0
169: 		l.Phase = out.Next
170: 		l.State = "starting"
171: 		l.SessionID = ""
172: 		_, _ = l.Queue.Start()
173: 		actions = append(actions, Action{Kind: "start_check", Phase: l.Phase})
174: 	case "smoke", "operator":
