178: 		actions = append(actions, Action{Kind: "post", Milestone: control.Milestone{
179: 			Kind:     "stop",
180: 			Headline: finished + " done: stop after " + out.Stop,
181: 			Numbers:  "next " + out.Next + " · waiting for continue",
182: 		}})
183: 	case "end":
184: 		l.State = "waiting"
185: 		l.Stop = &control.Stop{Kind: "end", Phase: finished, Reason: "plan complete", At: now}
