216: // Continue clears a stop and asks the loop to resume or begin the next phase.
217: func (l *Loop) Continue(now time.Time) ([]Action, error) {
218: 	if l.State != "waiting" {
219: 		return nil, control.ErrNotWaiting
220: 	}
221: 	if l.Stop != nil && l.Stop.Kind == "not_pushed" {
222: 		if _, err := l.Queue.Continue(); err != nil {
223: 			return nil, err
224: 		}
225: 		if _, err := l.Queue.Start(); err != nil {
226: 			return nil, err
227: 		}
228: 		l.State = "running"
229: 		l.Stop = nil
230: 		return []Action{{Kind: "end_check", Phase: l.Phase}}, nil
231: 	}
232: 	if _, err := l.Queue.Continue(); err != nil {
233: 		return nil, err
234: 	}
235: 	ph, err := l.Queue.Start()
236: 	if err != nil {
237: 		return nil, err
238: 	}
239: 	l.Phase = ph.ID
240: 	l.State = "starting"
241: 	l.Stop = nil
242: 	l.Nudged = false
243: 	l.Alerted = false
244: 	l.SessionUSD = 0
245: 	l.SessionID = ""
246: 	return []Action{{Kind: "start_check", Phase: l.Phase}}, nil
247: }
