113: // Tick drives the timers: the resume after a pause, the wall clock cap and
114: // the stall nudge.
115: func (l *Loop) Tick(now time.Time, cfg Config) []Action {
116: 	if l.State == "paused" && !now.Before(l.PausedUntil) {
117: 		l.State = "running"
118: 		l.LastEventAt = now
119: 		return []Action{
120: 			{Kind: "write", Line: "Continue by docs/AUTONOMY.md from where you stopped; the usage window has reset."},
121: 			{Kind: "post", Milestone: control.Milestone{Kind: "watchdog", Headline: l.Phase + ": resumed after the limit"}},
122: 		}
123: 	}
124: 	if l.State != "running" {
125: 		return nil
126: 	}
127: 
128: 	caps := l.currentCaps()
129: 	if caps.Hours > 0 && now.Sub(l.PhaseStartedAt) >= time.Duration(caps.Hours*float64(time.Hour)) {
130: 		reason := fmt.Sprintf("wall clock cap %s h reached", strconv.FormatFloat(caps.Hours, 'f', -1, 64))
131: 		l.State = "waiting"
132: 		l.Stop = &control.Stop{Kind: "cap", Phase: l.Phase, Reason: reason, At: now}
133: 		l.Queue.Stop("cap")
134: 		return []Action{
135: 			{Kind: "kill"},
136: 			{Kind: "post", Milestone: control.Milestone{Kind: "stop", Headline: l.Phase + ": wall clock cap", Numbers: reason}},
137: 		}
138: 	}
139: 
140: 	if cfg.StallMinutes > 0 && !l.Nudged && now.Sub(l.LastEventAt) >= time.Duration(cfg.StallMinutes)*time.Minute {
141: 		l.Nudged = true
142: 		headline := fmt.Sprintf("%s: no events for %d min", l.Phase, cfg.StallMinutes)
