15: func init() {
16: 	startPump = func(d *Daemon, ctx context.Context, project string, p claude.Process, l *eventlog.Log) {
17: 		pr := d.projects[project]
18: 		if pr == nil {
19: 			return
20: 		}
21: 		done := make(chan struct{})
22: 		pr.pumps[p] = done
23: 		go func() {
24: 			defer close(done)
25: 			d.pump(ctx, project, p, l)
26: 		}()
27: 	}
28: }
