30: // pump reads every line of p, records it, folds it into the session machine
31: // and the supervisor loop, and runs the actions they return. It closes when
32: // p.Lines() closes, at which point it consumes the exit status: if p is still
33: // the project's current process the loop sees the exit, otherwise nothing.
34: func (d *Daemon) pump(ctx context.Context, project string, p claude.Process, l *eventlog.Log) {
35: 	for line := range p.Lines() {
36: 		d.mu.Lock()
37: 		pr := d.projects[project]
38: 		if pr == nil {
39: 			d.mu.Unlock()
40: 			continue
41: 		}
42: 
43: 		now := d.deps.Now()
44: 		msg := json.RawMessage(line)
45: 		if !json.Valid(msg) {
46: 			if b, err := json.Marshal(string(line)); err == nil {
47: 				msg = b
48: 			}
49: 		}
50: 		if l != nil {
51: 			_, _ = l.Append("out", msg, now)
52: 		}
53: 
54: 		ev, err := stream.Parse(line)
55: 		if err == nil && pr.proc == p && pr.machine != nil {
56: 			pr.state.Loop.Event(now)
57: 			macts := pr.machine.Apply(ev, now)
58: 
59: 			var lacts []supervisor.Action
60: 			switch ev.Type {
61: 			case "result":
62: 				if ev.Result != nil {
63: 					lacts = pr.state.Loop.Turn(*ev.Result, now, d.deps.Config.Loop)
64: 				}
65: 			case "rate_limit_event":
66: 				if ev.Limits != nil {
67: 					lacts = pr.state.Loop.Limits(*ev.Limits, now, d.deps.Config.Loop)
68: 				}
69: 			}
70: 
71: 			for _, a := range macts {
72: 				switch a.Kind {
73: 				case "write":
74: 					d.writeLine(project, a.Line)
75: 				case "ask":
76: 					_, _ = d.deps.Post(ctx, project, "ask", a.Headline, a.Numbers)
77: 				case "turn":
78: 					headline := a.Headline
79: 					if r := []rune(headline); len(r) > 200 {
80: 						headline = string(r[:200])
81: 					}
82: 					if headline == "" {
83: 						headline = "(no text)"
84: 					}
85: 					_, _ = d.deps.Post(ctx, project, "idle", pr.state.Loop.Phase+" turn ended: "+headline, a.Numbers)
86: 				case "limit":
87: 				}
88: 			}
89: 
90: 			d.execute(ctx, project, lacts)
91: 		}
92: 		d.mu.Unlock()
93: 	}
94: 
95: 	st := <-p.Exit()
96: 	d.mu.Lock()
97: 	pr := d.projects[project]
98: 	if pr != nil && pr.proc == p {
99: 		pr.proc = nil
100: 		d.execute(ctx, project, pr.state.Loop.Exited(st.Code, d.deps.Now(), d.deps.Config.Loop))
101: 	}
102: 	d.mu.Unlock()
103: }
