105: // Wait blocks until every pump of project whose process is not the current
106: // one has finished. It returns immediately when there is nothing to wait for.
107: func (d *Daemon) Wait(project string) {
108: 	d.mu.Lock()
109: 	var dones []chan struct{}
110: 	if pr := d.projects[project]; pr != nil {
111: 		for p, done := range pr.pumps {
112: 			if p == pr.proc {
113: 				continue
114: 			}
115: 			dones = append(dones, done)
116: 		}
117: 	}
118: 	d.mu.Unlock()
119: 
120: 	for _, done := range dones {
121: 		<-done
122: 	}
123: }

