82: // Open builds a daemon around d, loading every registered project.
83: func Open(ctx context.Context, d Deps) (*Daemon, error) {
84: 	dm := &Daemon{deps: d, ctx: ctx, projects: map[string]*proj{}}
85: 	dm.mu.Lock()
86: 	defer dm.mu.Unlock()
87: 
88: 	for _, p := range d.Registry.List() {
89: 		var st State
90: 		err := d.Registry.LoadState(p.Name, &st)
91: 		if err != nil {
92: 			if errors.Is(err, registry.ErrNoState) {
93: 				st = State{Loop: *supervisor.New(p.Name, queue.Queue{})}
94: 			} else {
95: 				return nil, err
96: 			}
97: 		}
98: 		dm.projects[p.Name] = &proj{
99: 			reg:   p,
100: 			state: st,
101: 			pumps: map[claude.Process]chan struct{}{},
102: 		}
103: 	}
104: 
105: 	for _, p := range d.Registry.List() {
106: 		pr := dm.projects[p.Name]
107: 		switch pr.state.Loop.State {
108: 		case "running", "starting", "paused":
109: 			dm.execute(ctx, p.Name, pr.state.Loop.Exited(-2, d.Now(), d.Config.Loop))
110: 		}
111: 	}
112: 	return dm, nil
113: }
