220: // Status reports the state of one project.
221: func (d *Daemon) Status(project string) (control.Status, error) {
222: 	d.mu.Lock()
223: 	defer d.mu.Unlock()
224: 
225: 	pr, ok := d.projects[project]
226: 	if !ok {
227: 		return control.Status{}, control.ErrUnknownProject
228: 	}
229: 	loop := pr.state.Loop
230: 
231: 	var out control.Status
232: 	out.State = loop.State
233: 	if loop.State == "running" && pr.machine != nil && pr.proc != nil {
234: 		out.State = pr.machine.State
235: 	}
236: 	out.Phase = loop.Phase
237: 	if loop.State == "running" || loop.State == "paused" {
238: 		out.Minutes = int(d.deps.Now().Sub(loop.PhaseStartedAt).Minutes())
239: 	}
240: 	if pr.machine != nil {
241: 		out.CostUSD = pr.machine.CostUSD
242: 		if pr.machine.Limits != nil {
243: 			out.FiveHour = control.Percent(pr.machine.Limits.FiveHour.Utilization)
244: 			out.SevenDay = control.Percent(pr.machine.Limits.SevenDay.Utilization)
245: 		}
246: 		if pr.machine.SessionID != "" {
247: 			out.SessionID = pr.machine.SessionID
248: 		}
249: 	}
250: 	if out.SessionID == "" {
251: 		out.SessionID = loop.SessionID
252: 	}
253: 	out.Queue = queueView(loop.Queue)
254: 	out.Repo = pr.state.Repo
255: 	out.Stop = loop.Stop
256: 	return out, nil
257: }
