413: // PlanLoad installs a plan as the project's walking queue.
414: func (d *Daemon) PlanLoad(project string, plan queue.Plan) (control.QueueView, error) {
415: 	d.mu.Lock()
416: 	defer d.mu.Unlock()
417: 
418: 	pr, ok := d.projects[project]
419: 	if !ok {
420: 		return control.QueueView{}, control.ErrUnknownProject
421: 	}
422: 	if pr.state.Loop.State != "idle" && pr.state.Loop.State != "waiting" {
423: 		return control.QueueView{}, control.ErrBusy
424: 	}
425: 	q, err := queue.Load(plan, pr.reg.Caps)
426: 	if err != nil {
427: 		return control.QueueView{}, fmt.Errorf("%w: %v", control.ErrBadInput, err)
428: 	}
429: 	pr.state.Loop = *supervisor.New(project, q)
430: 	pr.queuedAt = d.deps.Now()
431: 
432: 	if d.runningCount() < d.deps.Config.MaxParallel {
433: 		acts, berr := pr.state.Loop.Begin(d.deps.Now())
434: 		if berr == nil {
435: 			d.execute(d.ctx, project, acts)
436: 		}
437: 	} else {
438: 		_ = d.deps.Registry.SaveState(project, pr.state)
439: 	}
440: 	return queueView(pr.state.Loop.Queue), nil
441: }
