591: // execute runs a batch of actions. It assumes d.mu is held.
592: func (d *Daemon) execute(ctx context.Context, project string, acts []supervisor.Action) {
593: 	pr := d.projects[project]
594: 	if pr == nil {
595: 		return
596: 	}
597: 	for _, a := range acts {
598: 		switch a.Kind {
599: 		case "start_check":
600: 			start := gitrules.StartCheck(ctx, d.deps.Runner, pr.reg.Dir)
601: 			d.execute(ctx, project, pr.state.Loop.StartChecked(start, d.deps.NewID, d.deps.Now()))
602: 
603: 		case "spawn":
604: 			if pr.proc != nil {
605: 				_ = pr.proc.Kill()
606: 			}
607: 			token := d.deps.NewID()
608: 			if err := d.deps.Registry.PutSecret(project, "session-token", token); err != nil {
609: 				d.execute(ctx, project, pr.state.Loop.Exited(-3, d.deps.Now(), d.deps.Config.Loop))
610: 				continue
611: 			}
612: 			base := d.deps.Registry.Base()
613: 			path, err := claude.WriteMCPConfig(
614: 				filepath.Join(base, project),
615: 				"morphd",
616: 				d.deps.Config.MCPBaseURL+"/mcp/"+project+"/session",
617: 				token,
618: 			)
619: 			if err != nil {
620: 				d.execute(ctx, project, pr.state.Loop.Exited(-3, d.deps.Now(), d.deps.Config.Loop))
621: 				continue
622: 			}
623: 			logPath := filepath.Join(base, project, "sessions", a.SessionID+".jsonl")
624: 			lg, err := eventlog.Open(logPath)
625: 			if err != nil {
626: 				d.execute(ctx, project, pr.state.Loop.Exited(-3, d.deps.Now(), d.deps.Config.Loop))
627: 				continue
628: 			}
629: 			launch := claude.Launch{
630: 				Bin:           d.deps.Config.ClaudeBin,
631: 				Dir:           pr.reg.Dir,
632: 				SessionID:     a.SessionID,
633: 				Resume:        a.Resume,
634: 				BudgetUSD:     a.BudgetUSD,
635: 				Model:         d.deps.Config.Model,
636: 				MCPConfigPath: path,
637: 				Extra:         d.deps.Config.ExtraArgs,
638: 			}
639: 			p, err := d.deps.Spawn(ctx, launch)
640: 			if err != nil {
641: 				d.execute(ctx, project, pr.state.Loop.Exited(-3, d.deps.Now(), d.deps.Config.Loop))
642: 				continue
643: 			}
644: 			pr.machine = session.New()
645: 			pr.proc = p
646: 			pr.log = lg
647: 			if startPump != nil {
648: 				startPump(d, ctx, project, p, lg)
649: 			}
650: 
651: 		case "first_line", "write":
652: 			if pr.machine == nil {
653: 				continue
654: 			}
655: 			_, inner := pr.machine.Order(a.Line, d.deps.Now())
656: 			for _, ia := range inner {
657: 				if ia.Kind == "write" {
658: 					d.writeLine(project, ia.Line)
659: 				}
660: 			}
661: 
662: 		case "end_check":
663: 			end := gitrules.EndCheck(ctx, d.deps.Runner, pr.reg.Dir, pr.state.Loop.Phase)
664: 			d.execute(ctx, project, pr.state.Loop.EndChecked(end, d.deps.Now()))
665: 
666: 		case "kill":
667: 			if pr.proc != nil {
668: 				_ = pr.proc.Kill()
669: 			}
670: 
671: 		case "post":
672: 			_, _ = d.deps.Post(ctx, project, a.Milestone.Kind, a.Milestone.Headline, a.Milestone.Numbers)
673: 		}
674: 	}
675: 	_ = d.deps.Registry.SaveState(project, pr.state)
676: }
