678: // Tick drives every project's timers and starts queued work when capacity
679: // permits.
680: func (d *Daemon) Tick(ctx context.Context) {
681: 	d.mu.Lock()
682: 	defer d.mu.Unlock()
683: 
684: 	for _, p := range d.deps.Registry.List() {
685: 		pr := d.projects[p.Name]
686: 		if pr == nil {
687: 			continue
688: 		}
689: 		acts := pr.state.Loop.Tick(d.deps.Now(), d.deps.Config.Loop)
690: 		if len(acts) > 0 {
691: 			d.execute(ctx, p.Name, acts)
692: 		}
693: 	}
694: 
695: 	for d.runningCount() < d.deps.Config.MaxParallel {
696: 		var best *proj
697: 		for _, p := range d.deps.Registry.List() {
698: 			pr := d.projects[p.Name]
699: 			if pr == nil {
700: 				continue
701: 			}
702: 			if pr.state.Loop.State != "idle" {
703: 				continue
704: 			}
705: 			if pr.state.Loop.Queue.State != "queued" {
706: 				continue
707: 			}
708: 			if best == nil || pr.queuedAt.Before(best.queuedAt) {
709: 				best = pr
710: 			}
711: 		}
712: 		if best == nil {
713: 			break
714: 		}
715: 		acts, err := best.state.Loop.Begin(d.deps.Now())
716: 		if err != nil {
717: 			break
718: 		}
719: 		d.execute(ctx, best.reg.Name, acts)
720: 	}
721: }
